let audio,on=false,master;
const notes={click:[620],message:[740,920],paper:[240,320],success:[330,440,660],failure:[160,130],scene:[220,330,440],ending:[220,277,330,440]};
export function fx(name='click'){if(!on||!audio)return;const t=audio.currentTime;(notes[name]||notes.click).forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type=name==='message'?'sine':'triangle';o.frequency.value=f;o.connect(g).connect(master);g.gain.setValueAtTime(0,t+i*.09);g.gain.linearRampToValueAtTime(name==='click'?.06:.11,t+i*.09+.012);g.gain.exponentialRampToValueAtTime(.001,t+i*.09+(name==='ending'?1.8:.35));o.start(t+i*.09);o.stop(t+i*.09+2);});}
export async function toggleSound(){if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=.25;master.connect(audio.destination);for(const f of [110,164.8,220]){const osc=audio.createOscillator(),gain=audio.createGain();osc.frequency.value=f;gain.gain.value=.012;osc.connect(gain).connect(master);osc.start();}}on=!on;if(on){await audio.resume();fx('message');}else await audio.suspend();return on;}
export function quiet(){if(audio&&on)audio.suspend();}export function resumeSound(){if(audio&&on)audio.resume();}
